using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.HotSpringSalt;

/// <summary>
/// Hot spring salt, white crusts left on the ash where hot water has welled up and dried, in the Ashlands. Salts meat
/// for curing. Model: generated by AssetSource/Tools/make_forage_models.py.
/// </summary>
public class HotSpringSalt : ForageableBase
{
    /// <summary>
    /// Prefab name of the hot spring salt item.
    /// </summary>
    public const string PrefabName = "WhiteHiltHotSpringSalt";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Hot Spring Salt";

    /// <inheritdoc/>
    protected override string Description => "A white crust scraped from the ash where hot water has welled up and dried. It salts meat that is to keep.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Flint";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Stone";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.AshLands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 2,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 2,
        GroupRadius = 3f,
        MinAltitude = 1f,
        MaxTilt = 15f,
        ScaleMin = 0.9f,
        ScaleMax = 1.2f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override float DefaultGroundClearance => 0.05f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, IsItem(visualRoot) ? "saltlump" : "saltcrust", 0.07f);
    }
}
